                if out[y][x] == 0:
                    out[y][x] = 5
            out[rr][cc] = color
            segments[color, r, c] = set(cells + [(r,c),(rr,cc)])
    # Crossings of horizontal color-2 and vertical color-6 rays create a 4 diagonal.
