def transform(grid):
    out = [row[:] for row in grid]
    vectors = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    h, w = len(grid), len(grid[0])
    segments = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in vectors:
                continue
            dr, dc = vectors[color]
            rr, cc = r + dr, c + dc
            if not (0 <= rr < h and 0 <= cc < w):
                continue
            cells = []
            if dc:
                step = 1 if dc > 0 else -1
                for x in range(c + step, cc + step, step):
                    cells.append((r, x))
            if dr:
                step = 1 if dr > 0 else -1
                for y in range(r + step, rr + step, step):
                    cells.append((y, cc))
            for y, x in cells:
                if out[y][x] == 0:
                    out[y][x] = 5
            out[rr][cc] = color
            segments[color, r, c] = set(cells + [(r,c),(rr,cc)])
    # The four-colored ray starts at intersection of the 2 and 6 connectors.
    # Along their common row/column crossing, continue diagonally down-left.
    for (color_a, ra, ca), cells_a in segments.items():
        if color_a != 2: continue
        for (color_b, rb, cb), cells_b in segments.items():
            if color_b != 6: continue
            intersections = cells_a & cells_b
            if intersections:
                y, x = min(intersections)
                while 0 <= y < h and 0 <= x < w:
                    out[y][x] = 4
                    y += 1; x -= 1
    return out
